#include <iostream>
#include <map>
#include <string>
#include <variant>
#include <vector>

using Reading = std::variant<int, std::string>;

int main()
{
    const std::vector<std::string> titles{"Orbits", "Atlas", "Atlas"};
    std::map<std::string, int> counts;
    for (const auto& title : titles) ++counts[title];
    for (const auto& [title, count] : counts)
        std::cout << title << ": " << count << '\n';
    const Reading reading{24};
    if (const int* pages = std::get_if<int>(&reading))
        std::cout << "Pages: " << *pages << '\n';
}
